// --- 3. 疾患ガイド用スクリプト ---
function filterGuideCard(id, btn) {
  const cards = document.querySelectorAll('#guide-cards-container .card');
  const links = document.querySelectorAll('.guide-nav-link');
  links.forEach(l => l.classList.remove('active'));
  if (btn) btn.classList.add('active');

  cards.forEach(c => {
    if (id === 'all' || c.id === id) {
      c.style.display = 'block';
    } else {
      c.style.display = 'none';
    }
  });
}

function printActiveGuideCard() {
  window.print();
}

function toggleFrameworkDetails(btn) {
  const details = document.getElementById('framework-details');
  if (!details) return;
  if (details.style.display === 'none') {
    details.style.display = 'block';
    btn.innerText = '▲ 閉じる';
  } else {
    details.style.display = 'none';
    btn.innerText = '▼ 開く';
  }
}

// --- 4. 処方・病態鑑別チャート用スクリプト ---
function switchProfilingView(targetClass, btn) {
  const btns = document.querySelectorAll('#tab-profiling .tab-btn');
  btns.forEach(b => {
    b.classList.remove('active');
    b.style.background = '#f1f5f9';
    b.style.color = '#334155';
  });
  if (btn) {
    btn.classList.add('active');
    btn.style.background = 'var(--primary)';
    btn.style.color = 'white';
  }

  const sections = document.querySelectorAll('.profiling-container .section-block, .profiling-container .content-block, .profiling-container .disease-section');
  sections.forEach(sec => {
    if (targetClass === 'all') {
      sec.style.display = 'block';
    } else if (sec.classList.contains(targetClass)) {
      sec.style.display = 'block';
    } else {
      sec.style.display = 'none';
    }
  });
}

function filterProfilingContent() {
  const input = document.getElementById('profSearchInput');
  if (!input) return;
  const query = input.value.toLowerCase();
  const rows = document.querySelectorAll('.profiling-container tr.searchable, .profiling-container .profile-card');
  rows.forEach(item => {
    const text = item.innerText.toLowerCase();
    if (text.includes(query)) {
      item.style.display = '';
    } else {
      item.style.display = 'none';
    }
  });
}

